# Builds supabase/all_migrations.sql: every migration in one file, for pasting into
# the Supabase SQL Editor of an empty project. Runs in a single transaction, so a
# failure leaves the database untouched. Records each migration in the CLI history
# so a later `supabase db push` only sends new ones. Never includes seed.sql.

$migrations = Get-ChildItem -Path "$PSScriptRoot\migrations" -Filter '*.sql' | Sort-Object Name
$out = New-Object System.Text.StringBuilder

[void]$out.AppendLine(@'
-- GWAY: all migrations in one file. Generated by supabase/bundle.ps1, do not edit.
-- Paste into the SQL Editor of an EMPTY project and run once.

begin;

do $$
begin
  if to_regclass('public.profiles') is not null then
    raise exception 'GWAY tables already exist. Use `supabase db push` for new migrations.';
  end if;
end $$;

-- Leftovers from running seed.sql by mistake (local demo accounts).
delete from auth.users where email like '%@gway.test';
'@)

foreach ($file in $migrations) {
  [void]$out.AppendLine("`n-- ===== $($file.Name) =====`n")
  [void]$out.AppendLine([System.IO.File]::ReadAllText($file.FullName, [System.Text.Encoding]::UTF8))
}

[void]$out.AppendLine(@'

-- Migration history, so `supabase db push` knows these are applied.
create schema if not exists supabase_migrations;
create table if not exists supabase_migrations.schema_migrations (
  version text not null primary key,
  statements text[],
  name text
);
'@)

foreach ($file in $migrations) {
  $version, $name = $file.BaseName -split '_', 2
  [void]$out.AppendLine("insert into supabase_migrations.schema_migrations (version, name) values ('$version', '$name');")
}

[void]$out.AppendLine("`ncommit;")

$target = "$PSScriptRoot\all_migrations.sql"
[System.IO.File]::WriteAllText($target, $out.ToString(), (New-Object System.Text.UTF8Encoding($false)))
Write-Output "Wrote $target ($($migrations.Count) migrations)"
